module logic;
use model {Summary,Event};
use util {reverse};
record Cursor {
 pending:List<Event>,
 balance:I64,
 rejected:I64,
 peak:I64,
 audit:List<I64>,
 locked:Bool
}

fn run(events:List<Event>,initial:I64)->Summary {
 let final=fold(i in List::length(events),state:Cursor=Cursor {
  pending:events,
  balance:initial,
  rejected:0,
  peak:initial,
  audit:List::empty<I64>(),
  locked:false
 }) {
  let event=List::head(state.pending);
  let next=match event {
   Credit(amount)=>if amount < 0 || amount > 1000000 {
    Cursor {
     pending:List::tail(state.pending),
     balance:state.balance,
     rejected:state.rejected+1,
     peak:state.peak,
     audit:List::prepend(state.balance,state.audit),
     locked:state.locked
    }
   } else {
    let balance=state.balance+amount;
    Cursor {
     pending:List::tail(state.pending),
     balance:balance,
     rejected:state.rejected,
     peak:if balance > state.peak {balance} else {state.peak},
     audit:List::prepend(balance,state.audit),
     locked:state.locked
    }
   },
   Debit(amount)=>if amount < 0 || amount > 1000000 || state.locked || amount > state.balance {
    Cursor {
     pending:List::tail(state.pending),
     balance:state.balance,
     rejected:state.rejected+1,
     peak:state.peak,
     audit:List::prepend(state.balance,state.audit),
     locked:state.locked
    }
   } else {
    let balance=state.balance-amount;
    Cursor {
     pending:List::tail(state.pending),
     balance:balance,
     rejected:state.rejected,
     peak:state.peak,
     audit:List::prepend(balance,state.audit),
     locked:state.locked
    }
   },
   Lock=>Cursor {
    pending:List::tail(state.pending),
    balance:state.balance,
    rejected:state.rejected,
    peak:state.peak,
    audit:List::prepend(state.balance,state.audit),
    locked:true
   },
   Unlock=>Cursor {
    pending:List::tail(state.pending),
    balance:state.balance,
    rejected:state.rejected,
    peak:state.peak,
    audit:List::prepend(state.balance,state.audit),
    locked:false
   }
  };
  next
 };
 Summary {
  balance:final.balance,
  rejected:final.rejected,
  peak:final.peak,
  audit:reverse(final.audit)
 }
}

